new:
let prompt = build_question_prompt(&turns);
let request = match self
    .acp
    .prepare_ask_session_request(&self.host, &session_id)
{
    Ok(request) => request,
    Err(error) => {
        self.status = Some(format!("Could not prepare ACP Ask session: {error}"));
        return;
    }
};
let config = match self.acp_runtime_startup_config(agent_id) {
    Ok(config) => config,
    Err(error) => {
        self.status = Some(error);
        return;
    }
};
let startup_status = config.starting_status().to_owned();
let task = match AcpSessionStartupTask::spawn(config, request) {
    Ok(task) => task,
    Err(error) => {
        self.status = Some(error);
        return;
    }
};
self.acp_startup = Some(AcpStartupState {
    agent_id: agent_id.to_owned(),
    target: AcpStartupTarget::Ask {
        gameengine_session_id: session_id,
        prompt,
    },
    task,
});
self.status = Some(startup_status);
